package app_test

// Wallet ⇄ chain native-tx compatibility proof.
//
// The Aethelred Wallet's `@aethelred/wallet-chain-cosmos` package builds
// SIGN_MODE_DIRECT transactions with a from-scratch protobuf writer and
// signs their SignDoc with the wallet's eth_secp256k1 (keccak, low-S)
// custody path. This test is the chain-side half of that contract:
//
//	 1. decode the EXACT TxRaw bytes the wallet produced (fixture below,
//	    generated by apps/extension/src/test/chain-cosmos.test.ts in the
//	    wallet repo with a fixed test key) using the app's own TxConfig —
//	    the same decoder the node runs;
//	 2. assert the message, fee, memo, pubkey, and sequence decode to the
//	    values the wallet claims to have encoded;
//	 3. rebuild the sign bytes via the app's SignModeHandler and verify the
//	    signature with ethsecp256k1.PubKey.VerifySignature — byte-for-byte
//	    the ante handler's signature verification path.
//
// A pass proves a wallet-built native transaction is protocol-valid to the
// real chain binary: canonical protobuf encoding, correct SignDoc binding
// (chain-id + account number), keccak digest, and 64-byte r‖s signature.

import (
	"context"
	"encoding/hex"
	"testing"

	sdk "github.com/cosmos/cosmos-sdk/types"
	"github.com/cosmos/cosmos-sdk/types/bech32"
	authsigning "github.com/cosmos/cosmos-sdk/x/auth/signing"
	banktypes "github.com/cosmos/cosmos-sdk/x/bank/types"
	"github.com/cosmos/evm/crypto/ethsecp256k1"
	signingtypes "github.com/cosmos/cosmos-sdk/types/tx/signing"
	"github.com/stretchr/testify/require"

	"github.com/aethelred/aethelred/app"
)

// Fixture generated by the wallet repo's chain-cosmos golden test
// (fixed RFC-6979 test key — NOT a real account key):
//
//	MsgSend(from=to=walletAddr, 1000000uaethel), memo "aethelred-native-e2e",
//	fee 5000uaethel / gas 200000, chain-id "aethelred-testnet-1",
//	account_number 7, sequence 3.
const (
	walletTxRawHex  = ""
	walletPubkeyHex = "02ee57c88c01ce009e89a270cec9aaca8197736c1766fb6e600feaa0ec9ea8a424"
	walletAddr      = "aethel1zg6x8f9sv4ezaxg3t4kzytex0kw2hdfydwvs8e"

	walletChainID       = "aethelred-testnet-1"
	walletAccountNumber = uint64(7)
	walletSequence      = uint64(3)
)

func TestWalletChainCosmos_NativeTxDecodesAndVerifies(t *testing.T) {
	enc := app.MakeEncodingConfig()

	txBytes, err := hex.DecodeString(walletTxRawHex)
	require.NoError(t, err, "fixture must be valid hex")

	// 1. Decode with the node's own tx decoder.
	decoded, err := enc.TxConfig.TxDecoder()(txBytes)
	require.NoError(t, err, "the app's decoder must accept the wallet's TxRaw")

	// 2. Message content round-trips exactly.
	msgs := decoded.GetMsgs()
	require.Len(t, msgs, 1)
	send, ok := msgs[0].(*banktypes.MsgSend)
	require.True(t, ok, "first message must decode as bank MsgSend")
	require.Equal(t, walletAddr, send.FromAddress)
	require.Equal(t, walletAddr, send.ToAddress)
	require.Len(t, send.Amount, 1)
	require.Equal(t, "uaethel", send.Amount[0].Denom)
	require.Equal(t, "1000000", send.Amount[0].Amount.String())

	// Fee + memo as encoded by the wallet.
	feeTx, ok := decoded.(sdk.FeeTx)
	require.True(t, ok)
	require.Equal(t, uint64(200000), feeTx.GetGas())
	require.Equal(t, "5000uaethel", feeTx.GetFee().String())
	memoTx, ok := decoded.(sdk.TxWithMemo)
	require.True(t, ok)
	require.Equal(t, "aethelred-native-e2e", memoTx.GetMemo())

	// 3. Signature: eth_secp256k1 pubkey, SIGN_MODE_DIRECT, and the pubkey's
	// keccak-derived address must BE the bech32 from-address (one key, one
	// account, two renderings).
	sigTx, ok := decoded.(authsigning.SigVerifiableTx)
	require.True(t, ok)
	sigs, err := sigTx.GetSignaturesV2()
	require.NoError(t, err)
	require.Len(t, sigs, 1)

	ethPub, ok := sigs[0].PubKey.(*ethsecp256k1.PubKey)
	require.True(t, ok, "pubkey must decode as cosmos/evm eth_secp256k1")
	require.Equal(t, walletPubkeyHex, hex.EncodeToString(ethPub.Key))
	require.Equal(t, walletSequence, sigs[0].Sequence)

	derived, err := bech32.ConvertAndEncode(app.AccountAddressPrefix, ethPub.Address().Bytes())
	require.NoError(t, err)
	require.Equal(t, walletAddr, derived,
		"wallet bech32 address must equal the chain's keccak-derived address")

	sigData, ok := sigs[0].Data.(*signingtypes.SingleSignatureData)
	require.True(t, ok)
	require.Equal(t, signingtypes.SignMode_SIGN_MODE_DIRECT, sigData.SignMode)
	require.Len(t, sigData.Signature, 64, "cosmos signatures are r||s")

	// 4. Ante-parity signature verification: rebuild the sign bytes with the
	// app's SignModeHandler (exactly what x/auth sigverify does) and verify
	// with the eth_secp256k1 pubkey (keccak256 digest inside).
	signerData := authsigning.SignerData{
		Address:       walletAddr,
		ChainID:       walletChainID,
		AccountNumber: walletAccountNumber,
		Sequence:      walletSequence,
		PubKey:        ethPub,
	}
	signBytes, err := authsigning.GetSignBytesAdapter(
		context.Background(), enc.TxConfig.SignModeHandler(),
		signingtypes.SignMode_SIGN_MODE_DIRECT, signerData, decoded)
	require.NoError(t, err)
	require.True(t, ethPub.VerifySignature(signBytes, sigData.Signature),
		"wallet signature must verify under the chain's own sign-bytes")

	// Tamper checks: a different chain-id or account number must break the
	// signature — the SignDoc binding is real, not incidental.
	for name, mutate := range map[string]func(authsigning.SignerData) authsigning.SignerData{
		"chain-id":       func(d authsigning.SignerData) authsigning.SignerData { d.ChainID = "aethelred-testnet-2"; return d },
		"account-number": func(d authsigning.SignerData) authsigning.SignerData { d.AccountNumber = 8; return d },
	} {
		tampered, err := authsigning.GetSignBytesAdapter(
			context.Background(), enc.TxConfig.SignModeHandler(),
			signingtypes.SignMode_SIGN_MODE_DIRECT, mutate(signerData), decoded)
		require.NoError(t, err)
		require.False(t, ethPub.VerifySignature(tampered, sigData.Signature),
			"signature must not verify with tampered %s", name)
	}
}
